type ApiResult<T> = Result<Json<T>, (StatusCode, Json<ErrorBody>)>;

#[derive(Clone)] struct AppState { db: Arc<Mutex<Connection>>, executor_host:String, executor_port:u16, laya_host:String, laya_port:u16 }
#[derive(Serialize)] struct ErrorBody { error: String }
fn error(status: StatusCode, message: impl Into<String>) -> (StatusCode, Json<ErrorBody>) { (status, Json(ErrorBody { error: message.into() })) }

#[derive(Clone, Serialize)] struct Dataset { id: i64, name: String, description: String, created_at: String, updated_at: String }
#[derive(Deserialize)] struct CreateDataset { name: String, description: String }
