fn trim(value: &str, field: &str, max: usize) -> Result<String, String> {
    let value = value.trim();
    if value.is_empty() { return Err(format!("{field} é obrigatório.")); }
    if value.chars().count() > max { return Err(format!("{field} aceita no máximo {max} caracteres.")); }
    Ok(value.to_owned())
}
fn with_db<T>(state: &AppState, f: impl FnOnce(&Connection) -> rusqlite::Result<T>) -> Result<T, (StatusCode, Json<ErrorBody>)> {
    let db = state.db.lock().map_err(|_| error(StatusCode::INTERNAL_SERVER_ERROR, "Banco indisponível."))?;
    f(&db).map_err(|e| error(StatusCode::INTERNAL_SERVER_ERROR, format!("Erro no banco: {e}")))
}
fn executor_request(state:&AppState,method:&str,path:&str,body:Option<&str>)->Result<Value,String>{
    let address=(state.executor_host.as_str(),state.executor_port).to_socket_addrs().map_err(|e|e.to_string())?.next().ok_or("Executor não resolvido")?;
    let mut stream=TcpStream::connect_timeout(&address,Duration::from_secs(5)).map_err(|e|format!("Executor indisponível: {e}"))?;
    stream.set_read_timeout(Some(Duration::from_secs(120))).map_err(|e|e.to_string())?;
    let payload=body.unwrap_or(""); let request=format!("{method} {path} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",state.executor_host,payload.len(),payload);
    stream.write_all(request.as_bytes()).map_err(|e|e.to_string())?;let mut response=String::new();stream.read_to_string(&mut response).map_err(|e|e.to_string())?;
    let (head,data)=response.split_once("\r\n\r\n").ok_or("Resposta HTTP inválida")?;let code=head.split_whitespace().nth(1).and_then(|v|v.parse::<u16>().ok()).unwrap_or(500);
    let value:Value=serde_json::from_str(data).map_err(|e|format!("Resposta JSON inválida: {e}"))?;if code>=400{return Err(value.get("message").or_else(||value.get("error")).and_then(Value::as_str).unwrap_or("Falha no executor").to_string())}Ok(value)
}
fn runtime_http_request(state:&AppState,method:&str,path:&str,body:Option<&str>)->Result<Value,String>{
    let address=(state.laya_host.as_str(),state.laya_port).to_socket_addrs().map_err(|e|e.to_string())?.next().ok_or("Runtime LAYA não resolvido")?;
    let mut stream=TcpStream::connect_timeout(&address,Duration::from_secs(5)).map_err(|e|format!("Runtime LAYA indisponível: {e}"))?;stream.set_read_timeout(Some(Duration::from_secs(300))).map_err(|e|e.to_string())?;
    let payload=body.unwrap_or("");let request=format!("{method} {path} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",state.laya_host,payload.len(),payload);stream.write_all(request.as_bytes()).map_err(|e|e.to_string())?;let mut response=String::new();stream.read_to_string(&mut response).map_err(|e|e.to_string())?;let(head,data)=response.split_once("\r\n\r\n").ok_or("Resposta HTTP inválida")?;let code=head.split_whitespace().nth(1).and_then(|v|v.parse::<u16>().ok()).unwrap_or(500);let value:Value=serde_json::from_str(data).map_err(|e|format!("Resposta LAYA inválida: {e}"))?;if code>=400{return Err(value.get("detail").or_else(||value.get("error")).and_then(Value::as_str).unwrap_or("Falha no runtime LAYA").to_string())}Ok(value)
}
fn runtime_request(state:&AppState,path:&str,body:&str)->Result<Value,String>{runtime_http_request(state,"POST",path,Some(body))}
fn validate_example(input:&CreateDatasetExample)->Result<(),String>{if input.id.trim().is_empty(){return Err("id é obrigatório.".into())}let _:Value=serde_json::from_str(&input.state).map_err(|_|"state deve conter JSON válido.".to_string())?;let questions:Value=serde_json::from_str(&input.questions).map_err(|_|"questions deve conter JSON válido.".to_string())?;let gold:Value=serde_json::from_str(&input.gold).map_err(|_|"gold deve conter JSON válido.".to_string())?;let q=questions.as_object().ok_or("questions deve ser objeto JSON.")?;let g=gold.as_object().ok_or("gold deve ser objeto JSON.")?;for(key,value)in q{let question=value.as_object().ok_or_else(||format!("questions.{key} deve ser objeto."))?;let kind=question.get("type").and_then(Value::as_str).ok_or_else(||format!("questions.{key}.type é obrigatório."))?;let answer=g.get(key).ok_or_else(||format!("gold.{key} está ausente."))?;match kind{"noul"=>{if !answer.is_boolean(){return Err(format!("gold.{key} deve ser booleano para noul."))}},"choice"=>{let selected=answer.as_str().ok_or_else(||format!("gold.{key} deve ser um label para choice."))?;let declared=question.get("labels").or_else(||question.get("choices")).and_then(Value::as_array).map(|labels|labels.iter().any(|v|v.as_str()==Some(selected))).or_else(||question.get("criteria").and_then(Value::as_object).map(|criteria|criteria.contains_key(selected))).ok_or_else(||format!("questions.{key} deve declarar labels, choices ou criteria para choice."))?;if !declared{return Err(format!("gold.{key} não pertence aos labels declarados."))}},"score"=>{if question.get("criteria").and_then(Value::as_array).map_or(true,|v|v.is_empty()){return Err(format!("questions.{key}.criteria é obrigatório para score."))}let score=answer.as_f64().or_else(||answer.get("score").and_then(Value::as_f64)).ok_or_else(||format!("gold.{key}.score deve ser numérico."))?;if !(0.0..=1.0).contains(&score){return Err(format!("gold.{key}.score deve estar entre 0 e 1."))}if let Some(p)=answer.get("probabilities").and_then(Value::as_object){let sum:f64=p.values().map(|v|v.as_f64().unwrap_or(-1.0)).sum();if p.values().any(|v|v.as_f64().map_or(true,|x|!(0.0..=1.0).contains(&x)))||(sum-1.0).abs()>0.001{return Err(format!("gold.{key}.probabilities deve somar 1."))}}},_=>return Err(format!("questions.{key}.type não é reconhecido pelo LAYA."))}}for key in g.keys(){if !q.contains_key(key){return Err(format!("gold.{key} não possui pergunta correspondente."))}}Ok(())}
fn example_from_json(value:Value)->Result<CreateDatasetExample,String>{let object=value.as_object().ok_or("A linha deve ser um objeto JSON.")?;let id=object.get("id").and_then(Value::as_str).ok_or("id é obrigatório.")?.to_string();let state=object.get("state").ok_or("state é obrigatório.")?.to_string();let questions=object.get("questions").ok_or("questions é obrigatório.")?.to_string();let gold=object.get("gold").ok_or("gold é obrigatório.")?.to_string();Ok(CreateDatasetExample{id,state,questions,gold})}
fn init_db(path: &str) -> rusqlite::Result<Connection> {
    if let Some(parent) = FsPath::new(path).parent() { std::fs::create_dir_all(parent).map_err(|_| rusqlite::Error::InvalidPath(FsPath::new(path).to_owned()))?; }
    let db = Connection::open(path)?;
    db.execute_batch("PRAGMA foreign_keys = ON; CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);")?;
    let version:i64=db.query_row("SELECT COALESCE(MAX(version),0) FROM schema_migrations",[],|r|r.get(0))?;
    if version < 1 { db.execute_batch("INSERT INTO schema_migrations(version) VALUES (1);")?; }
    if version < 2 { db.execute_batch("
        CREATE TABLE datasets (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
        CREATE TABLE dataset_imports (id INTEGER PRIMARY KEY, dataset_id INTEGER NOT NULL REFERENCES datasets(id) ON DELETE CASCADE, file_name TEXT NOT NULL, total_lines INTEGER NOT NULL DEFAULT 0, valid_lines INTEGER NOT NULL DEFAULT 0, invalid_lines INTEGER NOT NULL DEFAULT 0, duplicate_lines INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
        CREATE TABLE dataset_examples (id INTEGER PRIMARY KEY, dataset_id INTEGER NOT NULL REFERENCES datasets(id) ON DELETE CASCADE, import_id INTEGER REFERENCES dataset_imports(id) ON DELETE SET NULL, example_id TEXT NOT NULL, state_json TEXT NOT NULL, questions_json TEXT NOT NULL, gold_json TEXT NOT NULL, validation_status TEXT NOT NULL CHECK(validation_status IN ('valid','invalid')), validation_errors_json TEXT NOT NULL DEFAULT '[]', source TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(dataset_id,example_id));
        CREATE TABLE dataset_versions (id INTEGER PRIMARY KEY, dataset_id INTEGER NOT NULL REFERENCES datasets(id) ON DELETE RESTRICT, number INTEGER NOT NULL, example_count INTEGER NOT NULL, content_sha256 TEXT NOT NULL, contract_version TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(dataset_id,number));
        CREATE TABLE dataset_version_examples (dataset_version_id INTEGER NOT NULL REFERENCES dataset_versions(id) ON DELETE CASCADE, example_id TEXT NOT NULL, state_json TEXT NOT NULL, questions_json TEXT NOT NULL, gold_json TEXT NOT NULL, PRIMARY KEY(dataset_version_id,example_id));
        INSERT INTO schema_migrations(version) VALUES (2);")?; }
    if version < 3 { db.execute_batch("CREATE TABLE dataset_import_errors (id INTEGER PRIMARY KEY, import_id INTEGER NOT NULL REFERENCES dataset_imports(id) ON DELETE CASCADE, line_number INTEGER NOT NULL, example_id TEXT, field TEXT, reason TEXT NOT NULL); INSERT INTO schema_migrations(version) VALUES (3);")?; }
    if version < 4 { db.execute_batch("CREATE TABLE training_runs (id INTEGER PRIMARY KEY, dataset_version_id INTEGER NOT NULL REFERENCES dataset_versions(id) ON DELETE RESTRICT, status TEXT NOT NULL CHECK(status IN ('draft','configured','submitted','running','succeeded','failed')), kaggle_kernel_ref TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); INSERT INTO schema_migrations(version) VALUES (4);")?; }
    if version < 5 { db.execute_batch("
        ALTER TABLE training_runs ADD COLUMN executor_run_id TEXT;
        ALTER TABLE training_runs ADD COLUMN kaggle_url TEXT;
        ALTER TABLE training_runs ADD COLUMN logs_json TEXT NOT NULL DEFAULT '[]';
        ALTER TABLE training_runs ADD COLUMN error TEXT;
        CREATE TABLE model_artifacts (id INTEGER PRIMARY KEY, training_run_id INTEGER NOT NULL REFERENCES training_runs(id) ON DELETE RESTRICT, kind TEXT NOT NULL, name TEXT NOT NULL, bytes INTEGER NOT NULL, sha256 TEXT NOT NULL UNIQUE, tensor_count INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
        CREATE TABLE active_models (id INTEGER PRIMARY KEY, artifact_id INTEGER NOT NULL UNIQUE REFERENCES model_artifacts(id) ON DELETE RESTRICT, activated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
        INSERT INTO schema_migrations(version) VALUES (5);")?; }
    if version < 6 { db.execute_batch("ALTER TABLE model_artifacts ADD COLUMN model_path TEXT; INSERT INTO schema_migrations(version) VALUES (6);")?; }
    if version < 7 { db.execute_batch("DROP TABLE IF EXISTS training_job_items; DROP TABLE IF EXISTS training_jobs; DROP TABLE IF EXISTS content; DROP TABLE IF EXISTS folders; INSERT INTO schema_migrations(version) VALUES (7);")?; }
    Ok(db)
}

async fn health() -> &'static str { "ok\n" }
